  WESTERN,
  ARABIC_INDIC,
  PERSIAN,
  ANY_DIGIT_RE,
  ANY_DIGIT_GLOBAL,
  systemOf,
  digitValue,
  toNumber,
  censusNumerals,
  censusDesign,
  convertNumerals,
  findDates,
  checkDates,
  findCurrency,
  CURRENCIES,
