  quote: '<path d="M26 40c-7 0-12-5-12-12s5-12 12-12v10a6 6 0 0 0 0 12v2Z"/>'
    + '<path d="M50 40c-7 0-12-5-12-12s5-12 12-12v10a6 6 0 0 0 0 12v2Z"/>',
